style.css:
@-moz-document domain("google.com") {
/* Fondo de Google */
  body {
    background-color: #f5f5dc !important; /* Fondo beige por si la imagen no carga */
    background-image: url("https://i.pinimg.com/736x/c1/5d/09/c15d09a36b3abc431cda27f92708561f.jpg") !important; /* Imagen de fondo */
    background-size: cover !important; /* Ajusta la imagen al tamaño de la pantalla */
    background-attachment: fixed !important; /* Fija el fondo mientras haces scroll */
    font-family: 'Arial', sans-serif !important; /* Fuente legible */
    color: #4b3621 !important; /* Color marrón para texto */
  }

  /* Texto del buscador */
  input[type="text"] {
    background-color: #fffaf0 !important; /* Fondo claro para el cuadro de búsqueda */
    color: #4b3621 !important; /* Texto marrón */
    border-radius: 15px !important; /* Bordes redondeados */
    border: 2px solid #d2b48c !important; /* Borde beige */
    padding: 10px !important; /* Espaciado interno */
    font-size: 16px !important; /* Tamaño del texto */
  }

  /* Botones */
  input[type="submit"], button {
    background-color: #d2b48c !important; /* Color beige para botones */
    color: #4b3621 !important; /* Texto marrón oscuro */
    border-radius: 10px !important; /* Bordes redondeados */
    border: 2px solid #bc8f8f !important; /* Borde marrón claro */
    padding: 10px 15px !important; /* Espaciado interno */
    font-size: 14px !important; /* Tamaño del texto */
    font-weight: bold !important; /* Texto en negrita */
  }

  /* Enlaces */
  a {
    color: #8b4513 !important; /* Enlaces marrón oscuro */
    text-decoration: none !important; /* Sin subrayado */
  }

  a:hover {
    color: #d2b48c !important; /* Color beige al pasar el mouse */
    text-decoration: underline !important; /* Subrayado al pasar el mouse */
  }

  /* Texto general */
  h1, h2, h3, p, span {
    font-family: 'Georgia', serif !important; /* Fuente más elegante y legible */
    color: #4b3621 !important; /* Marrón oscuro para el texto */
  }

  /* Fondo del pie de página y barra de navegación (opcional) */
  footer, nav {
    background-color: #f5f5dc !important; /* Fondo beige */
    color: #4b3621 !important; /* Texto marrón oscuro */
    padding: 10px !important; /* Espaciado */
    border-top: 2px solid #d2b48c !important; /* Borde superior */
  }
}

/* Logo de Google en monocromático */
img[alt="Google"] {
  filter: grayscale(100%) !important; /* Convierte el logo a blanco y negro */
  opacity: 0.8 !important; /* Ajusta la transparencia */
}
